import { readdirSync, readFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

/** Generated file, relative to apps/wpsync. */
export const EMBED_PATH = "src/generated/embedded.ts";

const REPO = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");

/** Folders whose files the CLI carries inside itself, by export name. */
const SOURCES: Record<string, { dir: string; doc: string }> = {
  BRIDGE_FILES: {
    dir: join(REPO, "packages", "bridge-plugin", "wpsync-bridge"),
    doc: "The bridge plugin, keyed by path inside its folder (zipped and uploaded by connect).",
  },
  LOCAL_BRIDGE_FILES: {
    dir: join(REPO, "packages", "bridge-plugin", "local"),
    doc: "Scripts run inside the local DDEV site with wp eval-file (the push exporter).",
  },
  SITE_TEMPLATE_FILES: {
    dir: join(REPO, "packages", "site-template", "files"),
    doc: "Files every site project starts with (packages/site-template/files).",
  },
  RULES_FILES: {
    dir: join(REPO, "claude-plugin", "rules"),
    doc: "Rules for Claude copied into each site's CLAUDE.md (claude-plugin/rules), in file-name order.",
  },
};

function listFiles(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true })
    .flatMap((entry) => {
      const full = join(dir, entry.name);
      if (entry.name.startsWith(".")) return [];
      return entry.isDirectory() ? listFiles(full) : [full];
    })
    .sort();
}

/** The generated module's source. */
export function renderEmbedded(): string {
  const lines = ["/**", " * GENERATED by `pnpm generate` (scripts/embed.ts). Do not edit.", " */", ""];
  for (const [name, { dir, doc }] of Object.entries(SOURCES)) {
    lines.push(`/** ${doc} */`, `export const ${name}: Readonly<Record<string, string>> = {`);
    for (const full of listFiles(dir)) {
      const path = relative(dir, full).split("\\").join("/");
      lines.push(`  ${JSON.stringify(path)}: ${JSON.stringify(readFileSync(full, "utf8"))},`);
    }
    lines.push("};", "");
  }
  return lines.join("\n");
}
